    'art.cat.productivite':             'Productivity',
    'art.cat.quiz':                     'Quiz',
    'art.c19.title':                    'Artificial Intelligence as a Productivity Lever: Learn, Equip, Act',
    'art.c19.excerpt':                  'Where to learn AI for free, which tools to use and at what price, and how to turn the time saved into capital. Base44, ChatGPT, Gemini, Manus, Claude.',
    'art.c20.title':                    'Quiz: investment fees',
    'art.c20.excerpt':                  'Five questions to test what you know about investment fees: MER, hidden costs and their effect over thirty years.',
    /* ── Quiz link from the Fees article ── */
