    'sidebar.fiscalite.r1':             'Código',
    'sidebar.fiscalite.r2':             'Duración',
    'sidebar.fiscalite.r3':             'Modalidad',
    'sidebar.fiscalite.r3v':            'En línea',
    'sidebar.fiscalite.r4':             'Costo elegible',
    'sidebar.fiscalite.r5':             'Sesión',
    'sidebar.fiscalite.r5v':            'Otoño de 2026',
